        <Link className={styles.backToResults} to={catalogHref(date, "search")}>
          Search for food
        </Link>
      </div>
      <Form
        className={styles.searchForm}
        method="get"
        noValidate
        onSubmit={(event) => {
          if (validBarcode === undefined) {
            event.preventDefault();
            setClientMessage(
              "Enter a supported 7, 8, 12, 13, or 14 digit barcode.",
            );
          }
