/* eslint-disable @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-return -- react-test-renderer exposes host props as any */
import { createElement } from "react";
import { createRoutesStub } from "react-router";
import { act, create, type ReactTestRenderer } from "react-test-renderer";
import { expect, test } from "vitest";

import Setup from "../../app/routes/setup";

(globalThis as typeof globalThis & { IS_REACT_ACT_ENVIRONMENT: boolean })
  .IS_REACT_ACT_ENVIRONMENT = true;

async function renderSetup(
  actionData?: { error: string; field: string },
): Promise<ReactTestRenderer> {
  const Routes = createRoutesStub([
    { Component: Setup, id: "setup", path: "/setup" },
  ]);
  let renderer: ReactTestRenderer | undefined;
  await act(async () => {
    renderer = create(
      createElement(Routes, {
        hydrationData: {
          actionData: actionData ? { setup: actionData } : undefined,
          loaderData: { setup: { csrfToken: "component-csrf" } },
        },
        initialEntries: ["/setup"],
      }),
    );
  });
  return renderer!;
}

function input(renderer: ReactTestRenderer, name: string, value?: string) {
  return renderer.root.findAllByType("input").find((candidate) =>
    candidate.props.name === name &&
    (value === undefined || candidate.props.value === value),
  )!;
}

test("setup renders the complete control contract", async () => {
  const renderer = await renderSetup();
  expect(input(renderer, "csrfToken").props.value).toBe("component-csrf");
  expect(input(renderer, "displayUnits", "us").props.checked).toBe(true);
  expect(input(renderer, "displayUnits", "metric").props.checked).toBe(false);
  expect(input(renderer, "displayUnits", "us").props["aria-invalid"])
    .toBeUndefined();
  expect(input(renderer, "displayUnits", "metric").props["aria-invalid"])
    .toBeUndefined();
  expect(input(renderer, "displayUnits", "us").props["aria-describedby"])
    .toBeUndefined();
  expect(input(renderer, "displayUnits", "metric").props["aria-describedby"])
    .toBeUndefined();
  expect(input(renderer, "timeZone").props.value).toBe(
    Intl.DateTimeFormat().resolvedOptions().timeZone,
  );
  expect(input(renderer, "water").props).toMatchObject({
    max: "500",
    min: "0.001",
    step: "0.001",
    value: "80",
  });
  expect(input(renderer, "protein").props).toMatchObject({
    defaultValue: "120",
    max: "2000",
    min: "0.001",
    step: "0.001",
  });
  expect(input(renderer, "protein").props["aria-invalid"]).toBeUndefined();
  expect(input(renderer, "protein").props["aria-describedby"]).toBeUndefined();
  expect(input(renderer, "sodium").props).toMatchObject({
    defaultValue: "2300",
    max: "100000",
    min: "1",
    step: "1",
  });
  expect(renderer.root.findAllByType("label")).toHaveLength(11);
  expect(renderer.root.findAllByType("em").map((node) => node.children.join("")))
    .toEqual(["kcal", "fl oz", "g", "g", "g", "g", "g", "mg"]);
  renderer.unmount();
});

test.each([
  ["displayUnits", ["us", "metric"], "setup-error"],
  ["timeZone", [undefined], "setup-error time-zone-help"],
  ["water", [undefined], "setup-error"],
] as const)(
  "setup connects a %s error to exactly the affected controls",
  async (field, values, description) => {
    const renderer = await renderSetup({ error: `${field} failed`, field });
    const affected = values.map((value) => input(renderer, field, value));
    for (const control of affected) {
      expect(control.props["aria-invalid"]).toBe(true);
      expect(control.props["aria-describedby"]).toBe(description);
    }
    expect(
      renderer.root.findByProps({ id: "setup-error" }).children.join(""),
    ).toBe(`${field} failed`);
    if (field !== "displayUnits") {
      expect(input(renderer, "displayUnits", "us").props["aria-invalid"])
        .toBeUndefined();
    }
    if (field !== "timeZone") {
      expect(input(renderer, "timeZone").props["aria-invalid"]).toBeUndefined();
      expect(input(renderer, "timeZone").props["aria-describedby"]).toBe(
        "time-zone-help",
      );
    }
    expect(input(renderer, "protein").props["aria-invalid"]).toBeUndefined();
    expect(input(renderer, "protein").props["aria-describedby"])
      .toBeUndefined();
    renderer.unmount();
  },
);

test("unit controls update default water while preserving a customized draft", async () => {
  const renderer = await renderSetup();
  await act(async () => input(renderer, "displayUnits", "metric").props.onChange());
  expect(input(renderer, "displayUnits", "us").props.checked).toBe(false);
  expect(input(renderer, "displayUnits", "metric").props.checked).toBe(true);
  expect(input(renderer, "water").props).toMatchObject({
    max: "15000",
    value: "2366",
  });
  expect(renderer.root.findAllByType("em")[1].children.join("")).toBe("ml");

  await act(async () =>
    input(renderer, "water").props.onChange({ target: { value: "2600" } }),
  );
  await act(async () => input(renderer, "displayUnits", "us").props.onChange());
  expect(input(renderer, "displayUnits", "us").props.checked).toBe(true);
  expect(input(renderer, "displayUnits", "metric").props.checked).toBe(false);
  expect(input(renderer, "water").props.value).toBe("2600");

  await act(async () =>
    input(renderer, "timeZone").props.onChange({
      target: { value: "Pacific/Honolulu" },
    }),
  );
  expect(input(renderer, "timeZone").props.value).toBe("Pacific/Honolulu");
  renderer.unmount();
});

tests/database-schema-contract.test.ts.source:
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";

import { sql, type SQL } from "drizzle-orm";
import {
  getTableConfig,
  SQLiteSyncDialect,
  type SQLiteTable,
} from "drizzle-orm/sqlite-core";
import { expect, test } from "vitest";

import {
  openApplicationDatabase,
  type ApplicationDatabaseClient,
} from "../app/database/database.server";

type ColumnRow = {
  cid: number;
  dflt_value: string | null;
  name: string;
  notnull: 0 | 1;
  pk: number;
};

type ForeignKeyRow = {
  from: string;
  on_delete: string;
  table: string;
  to: string;
};

type IndexRow = {
  name: string;
  origin: string;
  unique: 0 | 1;
};

type IndexColumnRow = { name: string | null; seqno: number };
type SqlRow = { sql: string };

const dialect = new SQLiteSyncDialect();
type ConfiguredIndexColumn = ReturnType<
  typeof getTableConfig
>["indexes"][number]["config"]["columns"][number];

function rows<T>(client: ApplicationDatabaseClient, statement: string): T[] {
  return client.all(sql.raw(statement));
}

function canonicalSql(value: string): string {
  return value
    .replaceAll(/[`"]+/g, "")
    .replaceAll(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function configuredIndexColumnName(
  column: ConfiguredIndexColumn,
): string | null {
  if ("name" in column) return column.name;
  const rendered = canonicalSql(dialect.sqlToQuery(column).sql);
  return /(?:^|\.)([a-z_]+)(?:\s+collate\s+[a-z_]+)?(?:\s+(?:asc|desc))?$/
    .exec(rendered)?.[1] ?? null;
}

function defaultValue(value: unknown): string | null {
  if (value === undefined) return null;
  return String(value);
}

test("Drizzle schema metadata matches the migrated SQLite contract", async () => {
  // This second module identity is deliberately loaded during the test so
  // Stryker's static mutants are active before Drizzle builds its metadata.
  // @ts-expect-error Vite supports query-suffixed module identities.
  const schema = (await import("../app/database/schema.server?schema-contract")) as unknown as typeof import("../app/database/schema.server");
  const tables: SQLiteTable[] = [
    schema.applicationMetadata,
    schema.users,
    schema.passwordCredentials,
    schema.sessions,
    schema.preAuthenticationCsrfSessions,
    schema.rateLimitCounters,
    schema.userPreferences,
    schema.goalVersions,
    schema.foodEntries,
    schema.waterEvents,
  ];
  const directory = await mkdtemp(path.join(tmpdir(), "calory-schema-contract-"));
  const database = openApplicationDatabase({
    databasePath: path.join(directory, "application.sqlite"),
    migrationsFolder: path.resolve("drizzle"),
  });
  const client = database.getClient();

  try {
    for (const table of tables) {
      const config = getTableConfig(table);
      const tableSql = client.get<SqlRow>(
        sql`SELECT sql FROM sqlite_master WHERE type = 'table' AND name = ${config.name}`,
      );
      const columns = rows<ColumnRow>(
        client,
        `PRAGMA table_info("${config.name}")`,
      );

      expect(
        config.columns
          .map((column) => ({
            default: defaultValue(column.default),
            name: column.name,
            notNull: column.notNull,
          }))
          .sort((left, right) => left.name.localeCompare(right.name)),
      ).toEqual(
        columns
          .map((column) => ({
            default:
              column.dflt_value === null
                ? null
                : column.dflt_value.replace(/^'(.*)'$/, "$1"),
            name: column.name,
            notNull: Boolean(column.notnull) || Boolean(column.pk),
          }))
          .sort((left, right) => left.name.localeCompare(right.name)),
      );

      const configuredPrimaryKey = [
        ...config.columns.filter((column) => column.primary).map(({ name }) => name),
        ...config.primaryKeys.flatMap((key) => key.columns.map(({ name }) => name)),
      ];
      expect(configuredPrimaryKey).toEqual(
        columns
          .filter(({ pk }) => pk > 0)
          .sort((left, right) => left.pk - right.pk)
          .map(({ name }) => name),
      );

      const actualAutoIncrementColumns = [
        ...tableSql.sql.matchAll(
          /[`"]?([^`"\s]+)[`"]?\s+integer\s+primary key\s+autoincrement/gi,
        ),
      ].map((match) => match[1]);
      expect(
        config.columns
          .filter(
            (column) =>
              "autoIncrement" in column && Boolean(column.autoIncrement),
          )
          .map(({ name }) => name),
      ).toEqual(actualAutoIncrementColumns);

      const foreignKeys = rows<ForeignKeyRow>(
        client,
        `PRAGMA foreign_key_list("${config.name}")`,
      );
      expect(
        config.foreignKeys.map((foreignKey) => {
          const reference = foreignKey.reference();
          return {
            from: reference.columns[0]?.name,
            onDelete: foreignKey.onDelete?.toUpperCase(),
            table: getTableConfig(reference.foreignTable).name,
            to: reference.foreignColumns[0]?.name,
          };
        }),
      ).toEqual(
        foreignKeys.map((foreignKey) => ({
          from: foreignKey.from,
          onDelete: foreignKey.on_delete,
          table: foreignKey.table,
          to: foreignKey.to,
        })),
      );

      const indexes = rows<IndexRow>(
        client,
        `PRAGMA index_list("${config.name}")`,
      ).filter(({ origin }) => origin === "c");
      expect(
        config.indexes
          .map((index) => ({
            name: index.config.name,
            unique: index.config.unique,
          }))
          .sort((left, right) => left.name.localeCompare(right.name)),
      ).toEqual(
        indexes
          .map((index) => ({
            name: index.name,
            unique: Boolean(index.unique),
          }))
          .sort((left, right) => left.name.localeCompare(right.name)),
      );

      for (const index of config.indexes) {
        const actualColumns = rows<IndexColumnRow>(
          client,
          `PRAGMA index_info("${index.config.name}")`,
        )
          .sort((left, right) => left.seqno - right.seqno)
          .map(({ name }) => name);
        expect(index.config.columns).toHaveLength(actualColumns.length);
        expect(
          index.config.columns.map(configuredIndexColumnName),
        ).toEqual(actualColumns);

        for (const column of index.config.columns.filter(
          (candidate): candidate is SQL =>
            configuredIndexColumnName(candidate) === null,
        )) {
            const indexSql = client.get<SqlRow>(
              sql`SELECT sql FROM sqlite_master WHERE type = 'index' AND name = ${index.config.name}`,
            );
            const expression = dialect.sqlToQuery(column).sql;
            expect(canonicalSql(expression)).not.toBe("");
            expect(canonicalSql(indexSql.sql)).toContain(
              canonicalSql(expression).replace(`${config.name}.`, ""),
            );
        }
      }

      const actualCheckNames = [
        ...tableSql.sql.matchAll(/CONSTRAINT\s+"?([^"\s]+)"?\s+CHECK/gi),
      ].map((match) => match[1]);
      expect(config.checks.map(({ name }) => name)).toEqual(actualCheckNames);
      for (const check of config.checks) {
        const expression = dialect.sqlToQuery(check.value).sql;
        expect(canonicalSql(expression)).not.toBe("");
        expect(canonicalSql(tableSql.sql)).toContain(canonicalSql(expression));
      }
    }
  } finally {
    database.close();
    await rm(directory, { force: true, recursive: true });
  }
});

test("food snapshots accept coherent providers and reject mixed provider semantics", async () => {
  const directory = await mkdtemp(path.join(tmpdir(), "calory-provider-schema-"));
  const database = openApplicationDatabase({
    databasePath: path.join(directory, "application.sqlite"),
    migrationsFolder: path.resolve("drizzle"),
  });
  const client = database.getClient();

  const insert = (change: {
    authoritativeBaseUnit?: string;
    idempotencyKey: string;
    provider?: string;
    selectedMeasurementUnit?: string;
    sourceDataType?: string;
  }) =>
    client.run(sql.raw(`
      INSERT INTO food_entries (
        user_id, food_log_date, local_event_time, provider, provider_food_id,
        source_data_type, original_name, authoritative_base_unit,
        authoritative_base_quantity_microunits, selected_measurement_id,
        selected_measurement_label, selected_measurement_unit,
        selected_measurement_base_quantity_microunits, quantity_microunits,
        idempotency_key, created_at, updated_at
      ) VALUES (
        1, '2026-09-01', '12:00:00', '${change.provider ?? "open-food-facts"}',
        '0034000470693', '${change.sourceDataType ?? "Open Food Facts"}',
        'Example cereal', '${change.authoritativeBaseUnit ?? "serving"}',
        1000000, 'serving', '1 serving',
        '${change.selectedMeasurementUnit ?? "serving"}', 1000000, 1000000,
        '${change.idempotencyKey}', '2026-09-01T12:00:00.000Z',
        '2026-09-01T12:00:00.000Z'
      )
    `));

  try {
    client.run(sql.raw(
      "INSERT INTO users (id, username_normalized, created_at) VALUES (1, 'schema.owner', '2026-09-01T12:00:00.000Z')",
    ));
    expect(() => insert({ idempotencyKey: "valid-open-food-facts" }))
      .not.toThrow();
    expect(() =>
      insert({
        authoritativeBaseUnit: "g",
        idempotencyKey: "mixed-open-food-facts-unit",
        selectedMeasurementUnit: "g",
      }),
    ).toThrow();
    expect(() =>
      insert({
        idempotencyKey: "mixed-usda-source",
        provider: "usda-fdc",
      }),
    ).toThrow();
    expect(() =>
      insert({
        idempotencyKey: "unknown-provider",
        provider: "unknown",
      }),
    ).toThrow();
  } finally {
    database.close();
    await rm(directory, { force: true, recursive: true });
  }
});

