  const bodyChildren = Children.toArray(body.props.children) as ReactElement<{
    children?: ReactNode;
  }>[];
  expect(bodyChildren[0]).toMatchObject({
    props: { children: "Route body" },
    type: "p",
  });
});

test("root app renders its nested route outlet", async () => {
