test.each([
  [
    { data: "missing", internal: false, status: 404, statusText: "Not Found" },
    "Page not found",
    "This page does not exist.",
  ],
  [
    { data: "failure", internal: false, status: 500, statusText: "Failure" },
    "Something went wrong",
