import { createElement } from "react";
import { createRoutesStub } from "react-router";
import { act, create, type ReactTestRenderer } from "react-test-renderer";
import { describe, expect, test } from "vitest";

import ChangePassword, {
  headers as passwordHeaders,
  meta as passwordMeta,
} from "../../app/routes/account.password";
import Login, {
  headers as loginHeaders,
  meta as loginMeta,
} from "../../app/routes/login";
import Register, {
  headers as registerHeaders,
  meta as registerMeta,
} from "../../app/routes/register";

(globalThis as typeof globalThis & { IS_REACT_ACT_ENVIRONMENT: boolean })
  .IS_REACT_ACT_ENVIRONMENT = true;

async function renderRoute(
  Component: (props: never) => React.JSX.Element,
  path: string,
  loaderData: object,
  actionData?: object,
): Promise<ReactTestRenderer> {
  const Routes = createRoutesStub([{
    Component: Component as never,
    id: "subject",
    path,
  }]);
  let renderer: ReactTestRenderer | undefined;
  await act(async () => {
    renderer = create(
      createElement(Routes, {
        hydrationData: {
          actionData: actionData ? { subject: actionData } : undefined,
          loaderData: { subject: loaderData },
        },
        initialEntries: [path],
      }),
    );
  });
  return renderer!;
}

function input(renderer: ReactTestRenderer, name: string) {
  return renderer.root.findAllByType("input").find(
    (candidate) => candidate.props.name === name,
  )!;
}

function text(renderer: ReactTestRenderer): string {
  return renderer.root
    .findAll((node) => typeof node.type === "string")
    .flatMap((node) => node.children)
    .filter((child): child is string => typeof child === "string")
    .join(" ");
}

describe("authentication route metadata", () => {
  test.each([
    [loginMeta, "Sign in · Open Calory Tracker", "Sign in to your private account"],
    [registerMeta, "Register · Open Calory Tracker", "Create a private account"],
    [
      passwordMeta,
      "Change password · Open Calory Tracker",
      "Change your private account password",
    ],
  ] as const)("publishes an exact title and description", (meta, title, content) => {
    expect(meta()).toEqual([
      { title },
      { content, name: "description" },
    ]);
  });

  test.each([loginHeaders, registerHeaders, passwordHeaders])(
    "prevents authentication pages from being cached",
    (headers) => {
      expect(headers()).toEqual({ "Cache-Control": "no-store" });
    },
  );
});

describe("login component", () => {
  test("renders its complete submission contract without an error", async () => {
    const renderer = await renderRoute(
      Login,
      "/login",
      { csrfToken: "login-csrf" },
    );
    expect(input(renderer, "csrfToken").props).toMatchObject({
      type: "hidden",
      value: "login-csrf",
    });
    expect(input(renderer, "username").props).toMatchObject({
      autoComplete: "username",
      id: "login-username",
      maxLength: 30,
      required: true,
    });
    expect(input(renderer, "username").props.defaultValue).toBeUndefined();
    expect(input(renderer, "password").props).toMatchObject({
      autoComplete: "current-password",
      id: "login-password",
      required: true,
      type: "password",
    });
    expect(renderer.root.findByType("form").props).toMatchObject({
      method: "post",
      noValidate: true,
    });
    expect(renderer.root.findByType("button").children.join(""))
      .toBe("Sign in");
    expect(renderer.root.findAllByType("nav")).toHaveLength(0);
    expect(renderer.root.findAllByType("a")).toHaveLength(0);
    expect(renderer.root.findAllByProps({ role: "alert" })).toHaveLength(0);
    renderer.unmount();
  });

  test("preserves the attempted username and announces a failure", async () => {
    const renderer = await renderRoute(
      Login,
      "/login",
      { csrfToken: "login-csrf" },
      { error: "Credentials rejected", username: "Attempted.User" },
    );
    expect(input(renderer, "username").props.defaultValue)
      .toBe("Attempted.User");
    expect(renderer.root.findByProps({ role: "alert" }).children)
      .toContain("Credentials rejected");
    expect(text(renderer)).toContain("Couldn’t sign in");
    renderer.unmount();
  });

});

describe("registration component", () => {
  test("renders the exact account-creation controls", async () => {
    const renderer = await renderRoute(
      Register,
      "/register",
      { csrfToken: "register-csrf" },
    );
    expect(input(renderer, "csrfToken").props).toMatchObject({
      type: "hidden",
      value: "register-csrf",
    });
    expect(input(renderer, "username").props).toMatchObject({
      "aria-describedby": "register-username-help",
      autoComplete: "username",
      id: "register-username",
      maxLength: 30,
      pattern: "[A-Za-z0-9._-]+",
      required: true,
    });
    expect(input(renderer, "password").props).toMatchObject({
      "aria-describedby": "register-password-help",
      autoComplete: "new-password",
      id: "register-password",
      required: true,
      type: "password",
    });
    expect(input(renderer, "confirmPassword").props).toMatchObject({
      autoComplete: "new-password",
      id: "register-confirm-password",
      required: true,
      type: "password",
    });
    expect(text(renderer)).toContain(
      "3–30 letters, digits, dot, hyphen, or underscore.",
    );
    expect(text(renderer)).toContain(
      "12–128 characters; spaces, Unicode, paste, and password managers are supported.",
    );
    expect(renderer.root.findByType("button").children.join(""))
      .toBe("Create private account");
    expect(
      renderer.root.findAllByProps({ "aria-label": "Account access" }),
    ).toHaveLength(0);
    expect(renderer.root.findAllByProps({ role: "alert" })).toHaveLength(0);
    renderer.unmount();
  });

  test("preserves the username and exposes the route error", async () => {
    const renderer = await renderRoute(
      Register,
      "/register",
      { csrfToken: "register-csrf" },
      { error: "Username unavailable", username: "Taken.User" },
    );
    expect(input(renderer, "username").props.defaultValue).toBe("Taken.User");
    expect(renderer.root.findByProps({ role: "alert" }).children.join(""))
      .toBe("Username unavailable");
    renderer.unmount();
  });
});

describe("password component", () => {
  test.each([
    [undefined, undefined, undefined],
    [{ error: "Current password rejected" }, "Current password rejected", undefined],
    [{ changed: true }, undefined, "Password changed."],
  ] as const)(
    "renders the password state %#",
    async (actionData, expectedError, expectedStatus) => {
      const renderer = await renderRoute(
        ChangePassword,
        "/account/password",
        {
          csrfToken: "password-csrf",
          passwordChangeRequired: false,
          username: "account.owner",
        },
        actionData,
      );
      expect(input(renderer, "csrfToken").props.value).toBe("password-csrf");
      expect(input(renderer, "username").props).toMatchObject({
        autoComplete: "username",
        type: "hidden",
        value: "account.owner",
      });
      expect(input(renderer, "currentPassword").props).toMatchObject({
        autoComplete: "current-password",
        id: "current-password",
        required: true,
        type: "password",
      });
      expect(input(renderer, "newPassword").props).toMatchObject({
        "aria-describedby": "new-password-help",
        autoComplete: "new-password",
        id: "new-password",
        required: true,
        type: "password",
      });
      expect(input(renderer, "confirmNewPassword").props).toMatchObject({
        autoComplete: "new-password",
        id: "confirm-new-password",
        required: true,
        type: "password",
      });
      const errors = renderer.root.findAllByProps({ role: "alert" });
      expect(errors.map((node) => node.children.join("")))
        .toEqual(expectedError ? [expectedError] : []);
      const statuses = renderer.root.findAllByProps({ role: "status" });
      expect(statuses).toHaveLength(expectedStatus ? 1 : 0);
      if (expectedStatus) {
        expect(text(renderer)).toContain(expectedStatus);
        expect(text(renderer)).toContain("Other sessions were revoked.");
      }
      expect(text(renderer)).toContain(
        "Changing the password revokes other sessions and rotates this one.",
      );
      renderer.unmount();
    },
  );

  test("mandatory password onboarding exposes only replacement and logout", async () => {
    const renderer = await renderRoute(
      ChangePassword,
      "/account/password",
      {
        csrfToken: "restricted-csrf",
        passwordChangeRequired: true,
        username: "invited.member",
      },
    );
    expect(text(renderer)).toContain("Set your private password");
    expect(text(renderer)).toContain(
      "Replace the temporary password before continuing.",
    );
    expect(input(renderer, "currentPassword").props.autoFocus).toBe(true);
    expect(
      renderer.root.findAllByProps({ href: "/" }),
    ).toHaveLength(0);
    const forms = renderer.root.findAllByType("form");
    expect(forms).toHaveLength(2);
    expect(forms.at(-1)?.props).toMatchObject({ action: "/logout" });
    expect(text(renderer)).toContain("Sign out");
    expect(text(renderer)).not.toContain("temporary member passphrase");
    renderer.unmount();
  });
});

tests/goal-setup.test.ts.source:
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";

import { count, eq } from "drizzle-orm";
import { afterEach, expect, test } from "vitest";

import {
  openApplicationDatabase,
  type ApplicationDatabaseClient,
} from "../app/database/database.server";
import {
  goalVersions,
  userPreferences,
  users,
} from "../app/database/schema.server";
import { GoalSetupService } from "../app/setup/goal-setup.server";
import { setupClock } from "../app/setup/runtime.server";
import {
  validateSetupFields,
  type SetupSubmission,
} from "../app/setup/validation";

const temporaryDirectories: string[] = [];

afterEach(async () => {
  await Promise.all(
    temporaryDirectories.splice(0).map((directory) =>
      rm(directory, { force: true, recursive: true }),
    ),
  );
});

async function setupDatabase() {
  const directory = await mkdtemp(path.join(tmpdir(), "calory-setup-"));
  temporaryDirectories.push(directory);
  return openApplicationDatabase({
    databasePath: path.join(directory, "application.sqlite"),
    migrationsFolder: path.resolve("drizzle"),
  });
}

function insertUser(
  client: ApplicationDatabaseClient,
  username: string,
): number {
  return client
    .insert(users)
    .values({ createdAt: "2026-01-01T00:00:00.000Z", usernameNormalized: username })
    .returning({ id: users.id })
    .get().id;
}

const canonicalSetup: SetupSubmission = {
  calorieTargetMilliKcal: 2_000_000,
  carbohydrateTargetMilligrams: 200_000,
  displayUnits: "metric",
  fatTargetMilligrams: 70_000,
  fiberTargetMilligrams: 30_000,
  proteinTargetMilligrams: 100_000,
  sodiumMaximumMilligrams: 2_000,
  sugarMaximumMilligrams: 50_000,
  timeZone: "Pacific/Honolulu",
  waterTargetMicroliters: 2_500_000,
};

test("a database failure rolls back both halves of initial setup", async () => {
  const database = await setupDatabase();
  const client = database.getClient();
  const userId = insertUser(client, "atomic.user");
  const service = new GoalSetupService(
    client,
    () => new Date("2026-01-01T09:30:00.000Z"),
  );

  expect(() =>
    service.completeInitial(userId, {
      ...canonicalSetup,
      waterTargetMicroliters: -1,
    }),
  ).toThrow();

  expect(
    client
      .select({ value: count() })
      .from(userPreferences)
      .where(eq(userPreferences.userId, userId))
      .get()?.value,
  ).toBe(0);
  expect(
    client
      .select({ value: count() })
      .from(goalVersions)
      .where(eq(goalVersions.userId, userId))
      .get()?.value,
  ).toBe(0);
  database.close();
});

test("controlled local-date boundaries produce different initial effective dates", async () => {
  const database = await setupDatabase();
  const client = database.getClient();
  const honoluluUserId = insertUser(client, "honolulu.user");
  const kiritimatiUserId = insertUser(client, "kiritimati.user");
  const service = new GoalSetupService(
    client,
    () => new Date("2026-01-01T09:30:00.000Z"),
  );

  expect(service.completeInitial(honoluluUserId, canonicalSetup)).toEqual({
    effectiveDate: "2025-12-31",
    ok: true,
  });
  expect(
    service.completeInitial(kiritimatiUserId, {
      ...canonicalSetup,
      timeZone: "Pacific/Kiritimati",
    }),
  ).toEqual({ effectiveDate: "2026-01-01", ok: true });
  database.close();
});

test("initial setup refuses either half of a pre-existing setup", async () => {
  const database = await setupDatabase();
  const client = database.getClient();
  const preferenceUserId = insertUser(client, "preference.exists");
  const goalUserId = insertUser(client, "goal.exists");
  const createdAt = "2026-01-01T00:00:00.000Z";
  client.insert(userPreferences).values({
    createdAt,
    displayUnits: "metric",
    timeZone: "UTC",
    updatedAt: createdAt,
    userId: preferenceUserId,
  }).run();
  client.insert(goalVersions).values({
    ...canonicalSetup,
    createdAt,
    effectiveDate: "2026-01-01",
    userId: goalUserId,
  }).run();
  const service = new GoalSetupService(
    client,
    () => new Date("2026-01-01T12:00:00.000Z"),
  );

  expect(service.completeInitial(preferenceUserId, canonicalSetup)).toEqual({
    error: "already-complete",
    ok: false,
  });
  expect(service.completeInitial(goalUserId, canonicalSetup)).toEqual({
    error: "already-complete",
    ok: false,
  });
  database.close();
});

test.each([
  "SQLITE_CONSTRAINT_PRIMARYKEY",
  "SQLITE_CONSTRAINT_UNIQUE",
])("a %s race is reported as already complete", (code) => {
  const database = {
    transaction() {
      throw Object.assign(new Error("setup race"), { code });
    },
  } as unknown as ApplicationDatabaseClient;
  const service = new GoalSetupService(
    database,
    () => new Date("2026-01-01T12:00:00.000Z"),
  );

  expect(service.completeInitial(1, canonicalSetup)).toEqual({
    error: "already-complete",
    ok: false,
  });
});

test.each([
  new Error("ordinary failure"),
  Object.assign(new Error("different constraint"), {
    code: "SQLITE_CONSTRAINT_CHECK",
  }),
  { code: "SQLITE_CONSTRAINT_UNIQUE" },
])("non-race setup failures are rethrown", (error) => {
  const database = {
    transaction() {
      throw error;
    },
  } as unknown as ApplicationDatabaseClient;
  const service = new GoalSetupService(database);

  expect(() => service.completeInitial(1, canonicalSetup)).toThrow(error);
});

test("validation converts display values without SQLite floating point", () => {
  expect(
    validateSetupFields({
      calories: "1800.125",
      carbohydrate: "210.125",
      displayUnits: "us",
      fat: "60.5",
      fiber: "30.75",
      protein: "90.25",
      sodium: "1900",
      sugar: "45.5",
      timeZone: "America/New_York",
      water: "80",
    }),
  ).toMatchObject({
    data: {
      calorieTargetMilliKcal: 1_800_125,
      proteinTargetMilligrams: 90_250,
      waterTargetMicroliters: 2_365_882,
    },
    success: true,
  });
});

const validSetupFields = {
  calories: "2000",
  carbohydrate: "200",
  displayUnits: "metric",
  fat: "70",
  fiber: "30",
  protein: "100",
  sodium: "2000",
  sugar: "50",
  timeZone: "America/New_York",
  water: "2500",
};

test.each([
  ["decimal prefix", { calories: "1.000junk" }, "calories"],
  ["decimal suffix", { calories: "junk1.000" }, "calories"],
  ["integer prefix", { sodium: "1junk" }, "sodium"],
  ["integer suffix", { sodium: "junk1" }, "sodium"],
  ["zero calories", { calories: "0" }, "calories"],
  ["zero water", { water: "0" }, "water"],
] as const)("validation rejects a %s", (_label, change, field) => {
  expect(validateSetupFields({ ...validSetupFields, ...change })).toMatchObject({
    field,
    success: false,
  });
});

test("validation trims numeric values and returns every canonical field", () => {
  expect(
    validateSetupFields({
      ...validSetupFields,
      calories: " 2000 ",
      sodium: " 2000 ",
      timeZone: " Pacific/Honolulu ",
    }),
  ).toEqual({
    data: {
      calorieTargetMilliKcal: 2_000_000,
      carbohydrateTargetMilligrams: 200_000,
      displayUnits: "metric",
      fatTargetMilligrams: 70_000,
      fiberTargetMilligrams: 30_000,
      proteinTargetMilligrams: 100_000,
      sodiumMaximumMilligrams: 2_000,
      sugarMaximumMilligrams: 50_000,
      timeZone: "Pacific/Honolulu",
      waterTargetMicroliters: 2_500_000,
    },
    success: true,
  });
});

test("validation enforces time-zone boundaries and exact errors", () => {
  expect(
    validateSetupFields({ ...validSetupFields, displayUnits: "imperial" }),
  ).toEqual({
    error: "Choose US or metric display units.",
    field: "displayUnits",
    success: false,
  });
  expect(
    validateSetupFields({ ...validSetupFields, timeZone: "" }),
  ).toMatchObject({ field: "timeZone", success: false });
  expect(
    validateSetupFields({ ...validSetupFields, timeZone: "A".repeat(101) }),
  ).toEqual({
    error: "Enter a valid IANA time zone, such as America/New_York.",
    field: "timeZone",
    success: false,
  });
  expect(
    validateSetupFields({ ...validSetupFields, timeZone: "A".repeat(100) }),
  ).toMatchObject({ field: "timeZone", success: false });
});

test("validation exposes exact calorie, nutrient, and sodium errors", () => {
  expect(
    validateSetupFields({ ...validSetupFields, calories: "20000.001" }),
  ).toEqual({
    error: "Calories must be from 0.001 to 20,000 kcal.",
    field: "calories",
    success: false,
  });
  expect(
    validateSetupFields({ ...validSetupFields, protein: "2000.001" }),
  ).toEqual({
    error: "Protein must be from 0.001 to 2,000 g.",
    field: "protein",
    success: false,
  });
  expect(
    validateSetupFields({ ...validSetupFields, sodium: "100001" }),
  ).toEqual({
    error: "Sodium maximum must be from 1 to 100,000 mg.",
    field: "sodium",
    success: false,
  });
});

test("the setup clock only honors a valid test-only instant", () => {
  const originalNodeEnvironment = process.env.NODE_ENV;
  const originalSetupNow = process.env.SETUP_TEST_NOW;
  try {
    process.env.NODE_ENV = "test";
    process.env.SETUP_TEST_NOW = "2026-01-01T09:30:00.000Z";
    const clock = setupClock();
    expect(clock().toISOString()).toBe("2026-01-01T09:30:00.000Z");
    expect(clock()).not.toBe(clock());

    delete process.env.SETUP_TEST_NOW;
    const before = Date.now();
    expect(setupClock()().getTime()).toBeGreaterThanOrEqual(before);

    process.env.SETUP_TEST_NOW = "not-an-instant";
    expect(() => setupClock()).toThrow(
      "SETUP_TEST_NOW must be an ISO date-time",
    );

    process.env.NODE_ENV = "production";
    process.env.SETUP_TEST_NOW = "2026-01-01T09:30:00.000Z";
    expect(setupClock()().getTime()).toBeGreaterThan(
      new Date("2026-01-02T00:00:00.000Z").getTime(),
    );
  } finally {
    if (originalNodeEnvironment === undefined) delete process.env.NODE_ENV;
    else process.env.NODE_ENV = originalNodeEnvironment;
    if (originalSetupNow === undefined) delete process.env.SETUP_TEST_NOW;
    else process.env.SETUP_TEST_NOW = originalSetupNow;
  }
});

