import { expect, test } from "vitest";

import {
  foodEntrySnapshot,
  serializeCatalogMeasurements,
  type FoodEntryRow,
} from "../app/food-entry/snapshot.server";

function row(change: Partial<FoodEntryRow> = {}): FoodEntryRow {
  return {
    authoritativeBaseQuantityMicrounits: 100_000_000,
    authoritativeBaseUnit: "g",
    authoritativeNutrition:
      '{"carbohydrateMilligrams":null,"energyMilliKcal":null,"fatMilligrams":null,"fiberMilligrams":null,"proteinMilligrams":null,"sodiumMilligrams":null,"sugarMilligrams":null}',
    barcode: null,
    brand: null,
    carbohydrateMilligrams: null,
    createdAt: "2026-08-29T18:00:00.000Z",
    editedName: null,
    energyMilliKcal: null,
    fatMilligrams: null,
    fiberMilligrams: null,
    foodLogDate: "2026-08-29",
    id: 1,
    idempotencyKey: "snapshot-boundary",
    localEventTime: "14:00:00",
    marketCountry: null,
    originalName: "Boundary food",
    proteinMilligrams: null,
    provider: "usda-fdc",
    providerFoodId: "700",
    providerModifiedDate: null,
    providerPublishedDate: null,
    quantityMicrounits: 1_000_000,
    selectedMeasurementBaseQuantityMicrounits: 25_000_000,
    selectedMeasurementId: "portion:1",
    selectedMeasurementLabel: "1 portion",
    selectedMeasurementUnit: "g",
    sodiumMilligrams: null,
    sourceDataType: "Foundation",
    sugarMilligrams: null,
    supportedMeasurements: "[]",
    updatedAt: "2026-08-29T18:00:00.000Z",
    userId: 1,
    ...change,
  };
}

test("measurement serialization accepts mass, volume, and serving authority", () => {
  const measurements = [
    {
      baseQuantityMicrounits: 25_000_000,
      id: "portion:1",
      label: "1 portion",
      unit: "g" as const,
    },
    {
      baseQuantityMicrounits: 50_000_000,
      id: "volume:1",
      label: "1 cup",
      unit: "ml" as const,
    },
    {
      baseQuantityMicrounits: 1_000_000,
      id: "serving",
      label: "1 serving",
      unit: "serving" as const,
    },
  ];
  expect(JSON.parse(serializeCatalogMeasurements(measurements))).toEqual(
    measurements,
  );
  expect(() => serializeCatalogMeasurements([])).toThrow();
  expect(() =>
    serializeCatalogMeasurements([
      { ...measurements[0], unit: "oz" as "g" },
    ]),
  ).toThrow();
});

test.each(["[]", "{}"])(
  "an unusable %s measurement snapshot reconstructs selected and base choices",
  (supportedMeasurements) => {
    expect(foodEntrySnapshot(row({ supportedMeasurements }))).toMatchObject({
      supportedMeasurements: [
        {
          baseQuantityMicrounits: 25_000_000,
          id: "portion:1",
          label: "1 portion",
          unit: "g",
        },
        {
          baseQuantityMicrounits: 100_000_000,
          id: "base:g:100000000",
          label: "100 g",
          unit: "g",
        },
      ],
    });
  },
);

test("fallback does not duplicate a selected base measurement", () => {
  const snapshot = foodEntrySnapshot(
    row({
      selectedMeasurementBaseQuantityMicrounits: 100_000_000,
      selectedMeasurementId: "base:g:100000000",
      selectedMeasurementLabel: "100 g",
    }),
  );
  expect(snapshot.supportedMeasurements).toEqual([
    {
      baseQuantityMicrounits: 100_000_000,
      id: "base:g:100000000",
      label: "100 g",
      unit: "g",
    },
  ]);
});

test("a valid stored measurement snapshot is returned unchanged", () => {
  const stored = [
    {
      baseQuantityMicrounits: 10_000_000,
      id: "portion:stored",
      label: "Stored portion",
      unit: "g",
    },
  ];
  expect(
    foodEntrySnapshot(
      row({ supportedMeasurements: JSON.stringify(stored) }),
    ).supportedMeasurements,
  ).toEqual(stored);
});

tests/auth-validation.test.ts.source:
import { describe, expect, test } from "vitest";

import {
  loginSchema,
  memberPasswordResetSchema,
  passwordChangeSchema,
  registrationSchema,
} from "../app/auth/validation";

describe("authentication input validation", () => {
  test.each([
    ["AbC", "abc"],
    ["A._-9", "a._-9"],
    ["A".repeat(30), "a".repeat(30)],
  ])("accepts and normalizes the username %s", (username, normalized) => {
    expect(loginSchema.parse({ password: "present", username })).toEqual({
      password: "present",
      username: normalized,
    });
  });

  test.each([
    "ab",
    "a".repeat(31),
    "has space",
    "jalapeño",
    "slash/name",
  ])("rejects the username %s", (username) => {
    expect(loginSchema.safeParse({ password: "present", username }).success)
      .toBe(false);
  });

  test("login requires a non-empty password", () => {
    expect(loginSchema.safeParse({ password: "", username: "valid" }).success)
      .toBe(false);
  });

  test.each([
    ["a".repeat(11), false],
    ["a".repeat(12), true],
    ["🔐".repeat(12), true],
    ["a".repeat(128), true],
    ["a".repeat(129), false],
  ] as const)(
    "registration password code-point boundary has expected validity",
    (password, success) => {
      expect(
        registrationSchema.safeParse({
          confirmPassword: password,
          password,
          username: "valid-user",
        }).success,
      ).toBe(success);
    },
  );

  test("password length failures expose the stable validation contract", () => {
    const result = passwordChangeSchema.safeParse({
      confirmNewPassword: "too short",
      currentPassword: "current",
      newPassword: "too short",
    });

    expect(result.success).toBe(false);
    if (result.success) throw new Error("short password was accepted");
    expect(result.error.issues[0]).toMatchObject({
      code: "custom",
      message: "invalid password length",
      path: ["newPassword"],
    });
  });

  test("password changes identify confirmation mismatches", () => {
    const result = passwordChangeSchema.safeParse({
      confirmNewPassword: "different replacement password",
      currentPassword: "current",
      newPassword: "correct horse battery staple",
    });

    expect(result.success).toBe(false);
    if (result.success) throw new Error("mismatched passwords were accepted");
    expect(result.error.issues).toContainEqual(
      expect.objectContaining({
        code: "custom",
        message: "passwords do not match",
        path: ["confirmNewPassword"],
      }),
    );
  });

  test("registration identifies confirmation mismatches", () => {
    const result = registrationSchema.safeParse({
      confirmPassword: "different password",
      password: "correct horse battery staple",
      username: "valid-user",
    });

    expect(result.success).toBe(false);
    if (result.success) throw new Error("mismatched passwords were accepted");
    expect(result.error.issues).toContainEqual(
      expect.objectContaining({
        code: "custom",
        message: "passwords do not match",
        path: ["confirmPassword"],
      }),
    );
  });

  test.each([
    ["a".repeat(11), false],
    ["a".repeat(12), true],
    ["🔐".repeat(128), true],
    ["a".repeat(129), false],
  ] as const)(
    "member password reset shares the code-point password boundary",
    (password, success) => {
      expect(memberPasswordResetSchema.safeParse({
        confirmPassword: password,
        newPassword: password,
        targetUsername: "valid-user",
      }).success).toBe(success);
    },
  );

  test("password changes require both the current and a valid new password", () => {
    expect(
      passwordChangeSchema.safeParse({
        confirmNewPassword: "a".repeat(12),
        currentPassword: "",
        newPassword: "a".repeat(12),
      }).success,
    ).toBe(false);
    expect(
      passwordChangeSchema.safeParse({
        confirmNewPassword: "a".repeat(11),
        currentPassword: "current",
        newPassword: "a".repeat(11),
      }).success,
    ).toBe(false);
    expect(
      passwordChangeSchema.parse({
        confirmNewPassword: "a".repeat(12),
        currentPassword: "current",
        newPassword: "a".repeat(12),
      }),
    ).toEqual({
      confirmNewPassword: "a".repeat(12),
      currentPassword: "current",
      newPassword: "a".repeat(12),
    });
  });
});

tests/nutrition-boundaries.test.ts.source:
import { describe, expect, test } from "vitest";

import {
  quantityMicrounitsFromDecimal,
  scaleCatalogNutrient,
} from "../app/food-entry/nutrition";

describe("Food Entry quantity parsing", () => {
  test.each([
    ["0.000001", 1],
    ["1", 1_000_000],
    [" 1.2 ", 1_200_000],
    ["9.123456", 9_123_456],
    ["10", 10_000_000],
    ["99", 99_000_000],
  ] as const)("converts %s to %i microunits", (value, expected) => {
    expect(quantityMicrounitsFromDecimal(value)).toBe(expected);
  });

  test.each([
    "0",
    "0.000000",
    "99.000001",
    "100",
    "1.1234567",
    "1x",
    "x1",
    "-1",
    ".5",
  ])("rejects quantity %s", (value) => {
    expect(quantityMicrounitsFromDecimal(value)).toBeUndefined();
  });
});

describe("catalog nutrient fixed-point scaling", () => {
  test("preserves integer, decimal, and scientific coefficient forms", () => {
    expect(
      scaleCatalogNutrient(
        { amount: 12, fixedPointMultiplier: 1_000 },
        1_000_000,
        1_000_000,
        1_000_000,
      ),
    ).toBe(12_000);
    expect(
      scaleCatalogNutrient(
        { amount: 1.25, fixedPointMultiplier: 1_000 },
        1_000_000,
        1_000_000,
        1_000_000,
      ),
    ).toBe(1_250);
    expect(
      scaleCatalogNutrient(
        { amount: 1e-7, fixedPointMultiplier: 1_000_000_000 },
        1_000_000,
        1_000_000,
        1_000_000,
      ),
    ).toBe(100);
    expect(
      scaleCatalogNutrient(
        { amount: 1e21, fixedPointMultiplier: 1 },
        1,
        1_000_000,
        1_000_000_000_000_000,
      ),
    ).toBe(1_000_000);
  });

  test("null nutrients remain unavailable", () => {
    expect(scaleCatalogNutrient(null, 1, 1, 1)).toBeNull();
  });

  test.each([
    { amount: Number.NaN, fixedPointMultiplier: 1 },
    { amount: Number.POSITIVE_INFINITY, fixedPointMultiplier: 1 },
    { amount: -1, fixedPointMultiplier: 1 },
    { amount: 1, fixedPointMultiplier: 0 },
    { amount: 1, fixedPointMultiplier: -1 },
    { amount: 1, fixedPointMultiplier: 1.5 },
    { amount: 1, fixedPointMultiplier: Number.MAX_SAFE_INTEGER + 1 },
  ])("rejects invalid authoritative nutrient %#", (value) => {
    expect(() => scaleCatalogNutrient(value, 1, 1_000_000, 1)).toThrow(
      "Catalog nutrient is invalid",
    );
  });

  test("accepts zero amount and the minimum positive multiplier", () => {
    expect(
      scaleCatalogNutrient(
        { amount: 0, fixedPointMultiplier: 1 },
        1,
        1_000_000,
        1,
      ),
    ).toBe(0);
  });

  test("rejects a scaled result outside safe integer storage", () => {
    expect(() =>
      scaleCatalogNutrient(
        { amount: Number.MAX_VALUE, fixedPointMultiplier: 1 },
        1_000_000,
        1_000_000,
        1,
      ),
    ).toThrow("Food Entry exceeds storage limits");
  });
});

