tests/operational-logging.test.ts.source:
import { afterEach, describe, expect, test, vi } from "vitest";

import {
  operationalError,
  operationalLog,
} from "../server/operational-logging.js";

afterEach(() => {
  vi.restoreAllMocks();
  vi.unstubAllEnvs();
});

function loggedRecord(
  method: "error" | "log",
): Record<string, unknown> {
  const spy =
    method === "error" ? vi.mocked(console.error) : vi.mocked(console.log);
  expect(spy).toHaveBeenCalledOnce();
  return JSON.parse(String(spy.mock.calls[0]?.[0])) as Record<string, unknown>;
}

describe("operational logging", () => {
  test("info records are structured on stdout", () => {
    vi.spyOn(console, "log").mockImplementation(() => {});
    const stderr = vi.spyOn(console, "error").mockImplementation(() => {});

    operationalLog("info", "server_started", { port: 4173 });

    expect(loggedRecord("log")).toMatchObject({
      event: "server_started",
      level: "info",
      port: 4173,
      timestamp: expect.any(String) as unknown,
    });
    expect(stderr).not.toHaveBeenCalled();
  });

  test.each(["warn", "error"] as const)("%s records are structured on stderr", (level) => {
    const stdout = vi.spyOn(console, "log").mockImplementation(() => {});
    vi.spyOn(console, "error").mockImplementation(() => {});

    operationalLog(level, "request_failed", { status: 503 });

    expect(loggedRecord("error")).toMatchObject({
      event: "request_failed",
      level,
      status: 503,
    });
    expect(stdout).not.toHaveBeenCalled();
  });

  test("sensitive keys are redacted recursively without changing safe values", () => {
    vi.spyOn(console, "log").mockImplementation(() => {});

    operationalLog("info", "nested_details", {
      apiKey: "api-value",
      nested: {
        authorization: "bearer-value",
        ordinary: "visible",
      },
      rows: [{ cookie: "cookie-value" }, null, 7, false],
      session: "session-value",
    });

    expect(loggedRecord("log")).toMatchObject({
      apiKey: "[REDACTED]",
      nested: { authorization: "[REDACTED]", ordinary: "visible" },
      rows: [{ cookie: "[REDACTED]" }, null, 7, false],
      session: "[REDACTED]",
    });
  });

  test("key-value secrets embedded in text are fully redacted", () => {
    vi.spyOn(console, "log").mockImplementation(() => {});

    operationalLog("info", "unsafe_text", {
      message:
        "apiKey=alpha123&password=bravo-456; TOKEN=charlie_789 safe=value",
    });

    expect(loggedRecord("log")).toMatchObject({
      message:
        "apiKey=[REDACTED]&password=[REDACTED]; TOKEN=[REDACTED] safe=value",
    });
  });

  test("configured secret values are redacted longest-first wherever they occur", () => {
    vi.stubEnv("MUTATION_PASSWORD", "deployment-secret");
    vi.stubEnv("MUTATION_SECRET", "deployment-secret-with-suffix");
    vi.spyOn(console, "log").mockImplementation(() => {});

    operationalLog("info", "configured_secrets", {
      message: "deployment-secret-with-suffix and deployment-secret",
    });

    expect(loggedRecord("log")).toMatchObject({
      message: "[REDACTED] and [REDACTED]",
    });
  });

  test("Open Food Facts contact details are omitted from operational logs", () => {
    vi.stubEnv("OPEN_FOOD_FACTS_CONTACT_EMAIL", "private@example.test");
    vi.spyOn(console, "log").mockImplementation(() => {});

    operationalLog("info", "catalog_configuration", {
      contactEmail: "private@example.test",
      message: "configured for private@example.test",
    });

    expect(loggedRecord("log")).toMatchObject({
      contactEmail: "[REDACTED]",
      message: "configured for [REDACTED]",
    });

    vi.mocked(console.log).mockClear();
    operationalLog("info", "catalog_configuration", {
      "contact-email": "private@example.test",
      contact_email: "private@example.test",
      contactemail: "different@example.test",
    });
    expect(loggedRecord("log")).toMatchObject({
      "contact-email": "[REDACTED]",
      contact_email: "[REDACTED]",
      contactemail: "[REDACTED]",
    });
  });

  test("empty configured secrets do not alter ordinary log text", () => {
    vi.stubEnv("EMPTY_PASSWORD", "");
    vi.spyOn(console, "log").mockImplementation(() => {});

    operationalLog("info", "ordinary", { message: "remains visible" });

    expect(loggedRecord("log")).toMatchObject({ message: "remains visible" });
  });

  test("ordinary environment values remain visible", () => {
    vi.stubEnv("VISIBLE_SETTING", "visible-environment-value");
    vi.spyOn(console, "log").mockImplementation(() => {});

    operationalLog("info", "ordinary_environment", {
      message: "visible-environment-value",
    });

    expect(loggedRecord("log")).toMatchObject({
      message: "visible-environment-value",
    });
  });
});

describe("operational errors", () => {
  test("Error details retain their type while redacting their message", () => {
    vi.stubEnv("OWNER_PASSWORD", "deployment-secret");

    expect(
      operationalError(
        new TypeError("password=inline-secret deployment-secret"),
      ),
    ).toEqual({
      message: "password=[REDACTED] [REDACTED]",
      name: "TypeError",
    });
  });

  test("callers can omit Error messages", () => {
    expect(operationalError(new RangeError("private detail"), false)).toEqual({
      name: "RangeError",
    });
  });

  test("non-Error failures have a stable safe description", () => {
    expect(operationalError("password=unsafe")).toEqual({
      message: "Unknown operational failure",
      name: "UnknownError",
    });
    expect(operationalError({ reason: "unsafe" }, false)).toEqual({
      name: "UnknownError",
    });
  });
});

tests/server-startup.test.ts.source:
import { describe, expect, test } from "vitest";

import { validateServerConfiguration } from "../server/startup-configuration.js";

describe("server startup configuration", () => {
  const productionEnvironment = {
    APPLICATION_URL: "https://calories.example.test",
    NODE_ENV: "production",
    PORT: "4173",
    TRUST_PROXY: "172.30.0.0/16",
  };

  test("accepts a private production proxy and returns the listening port", () => {
    expect(validateServerConfiguration(productionEnvironment)).toEqual({
      port: 4173,
    });
  });

  test.each([undefined, "", "maintainer@example.test"])(
    "Open Food Facts contact %s never blocks startup or leaks into startup state",
    (OPEN_FOOD_FACTS_CONTACT_EMAIL) => {
      expect(
        validateServerConfiguration({
          ...productionEnvironment,
          OPEN_FOOD_FACTS_CONTACT_EMAIL,
        }),
      ).toEqual({ port: 4173 });
    },
  );

  test.each([
    [undefined, 3000],
    ["1", 1],
    ["65535", 65_535],
  ])("accepts development port %s", (PORT, port) => {
    expect(validateServerConfiguration({ NODE_ENV: "development", PORT })).toEqual(
      { port },
    );
  });

  test.each(["0", "65536", "not-a-port"])(
    "rejects invalid port %s",
    (PORT) => {
      expect(() =>
        validateServerConfiguration({ ...productionEnvironment, PORT }),
      ).toThrow("PORT must be an integer from 1 through 65535");
    },
  );

  test.each([
    "10.0.0.0/16",
    "10.255.255.255/32",
    "172.16.0.0/16",
    "172.31.255.255/32",
    "192.168.0.0/16",
    " 192.168.255.255/32 ",
  ])("accepts private production proxy CIDR %s", (TRUST_PROXY) => {
    expect(
      validateServerConfiguration({ ...productionEnvironment, TRUST_PROXY }),
    ).toEqual({ port: 4173 });
  });

  test.each([
    undefined,
    "",
    "10.0.0.0",
    "10.0.0.0/15",
    "10.0.0.0/33",
    "10.0.0.0/16 trailing",
    "prefix 10.0.0.0/16",
    "junk/10.0.0.0/16",
    "10.0.0/16",
    "2001:db8::/32",
    "11.0.0.0/16",
    "11.16.0.0/16",
    "11.168.0.0/16",
    "172.15.0.0/16",
    "172.32.0.0/16",
    "192.167.0.0/16",
    "192.169.0.0/16",
  ])("rejects unsafe production proxy CIDR %s", (TRUST_PROXY) => {
    expect(() =>
      validateServerConfiguration({ ...productionEnvironment, TRUST_PROXY }),
    ).toThrow(
      "TRUST_PROXY must be one private IPv4 Docker network CIDR with a prefix from 16 through 32",
    );
  });

  test("development does not require deployment URL or proxy settings", () => {
    expect(
      validateServerConfiguration({ NODE_ENV: "development", PORT: "3001" }),
    ).toEqual({ port: 3001 });
  });

  test.each([
    undefined,
    "",
  ])("requires an application URL outside development", (APPLICATION_URL) => {
    expect(() =>
      validateServerConfiguration({
        ...productionEnvironment,
        APPLICATION_URL,
        NODE_ENV: "test",
      }),
    ).toThrow("APPLICATION_URL is required outside development");
  });

  test.each([
    "https://user@calories.example.test",
    "https://user:password@calories.example.test",
    "https://calories.example.test/a-path",
    "https://calories.example.test?query=value",
    "https://calories.example.test#fragment",
  ])("rejects non-origin application URL %s", (APPLICATION_URL) => {
    expect(() =>
      validateServerConfiguration({
        ...productionEnvironment,
        APPLICATION_URL,
        NODE_ENV: "test",
      }),
    ).toThrow(
      "APPLICATION_URL must be an origin without credentials, path, query, or hash",
    );
  });

  test("permits HTTP application URLs outside production", () => {
    expect(
      validateServerConfiguration({
        APPLICATION_URL: "http://localhost:4173",
        NODE_ENV: "test",
        PORT: "4173",
      }),
    ).toEqual({ port: 4173 });
  });

  test("requires HTTPS application URLs in production", () => {
    expect(() =>
      validateServerConfiguration({
        ...productionEnvironment,
        APPLICATION_URL: "http://calories.example.test",
      }),
    ).toThrow("APPLICATION_URL must use HTTPS in production");
  });
});

tests/barcode-decoder.test.ts.source:
import {
  BarcodeFormat,
  type BrowserMultiFormatReader,
} from "@zxing/browser";
import {
  ChecksumException,
  DecodeHintType,
  FormatException,
  NotFoundException,
} from "@zxing/library";
import { afterEach, expect, test, vi } from "vitest";

const zxingHarness = vi.hoisted(() => ({
  callback: undefined as DecodeContinuouslyCallback | undefined,
  hints: undefined as Map<DecodeHintType, BarcodeFormat[]> | undefined,
  options: undefined as Record<string, number> | undefined,
  sessionStop: vi.fn(),
}));

vi.mock("@zxing/browser", async (importOriginal) => {
  const actual = await importOriginal<typeof import("@zxing/browser")>();
  return {
    ...actual,
    BrowserMultiFormatReader: class BrowserMultiFormatReaderDouble {
      constructor(
        hints: Map<DecodeHintType, BarcodeFormat[]>,
        options: Record<string, number>,
      ) {
        zxingHarness.hints = hints;
        zxingHarness.options = options;
      }

      scan(_video: HTMLVideoElement, callback: DecodeContinuouslyCallback) {
        zxingHarness.callback = callback;
        return { stop: zxingHarness.sessionStop };
      }
    },
  };
});

import { localBarcodeDecoder } from "../app/catalog/barcode-decoder.client";

type DecodeContinuouslyCallback = Parameters<
  BrowserMultiFormatReader["scan"]
>[1];

const originalBarcodeDetector = Object.getOwnPropertyDescriptor(
  globalThis,
  "BarcodeDetector",
);
const originalRequestAnimationFrame = globalThis.requestAnimationFrame;
const originalCancelAnimationFrame = globalThis.cancelAnimationFrame;

function restoreGlobal(name: string, descriptor?: PropertyDescriptor) {
  if (descriptor) {
    Object.defineProperty(globalThis, name, descriptor);
  } else {
    Reflect.deleteProperty(globalThis, name);
  }
}

afterEach(() => {
  restoreGlobal("BarcodeDetector", originalBarcodeDetector);
  globalThis.requestAnimationFrame = originalRequestAnimationFrame;
  globalThis.cancelAnimationFrame = originalCancelAnimationFrame;
  zxingHarness.callback = undefined;
  zxingHarness.hints = undefined;
  zxingHarness.options = undefined;
  zxingHarness.sessionStop.mockReset();
});

test("the local decoder requests the complete commercial format set and emits only manual-valid values", async () => {
  let requestedFormats: readonly string[] = [];
  const detect = vi.fn(async () => [
    { rawValue: "frame:data:image/png" },
    { rawValue: " 034000470693 " },
  ]);
  class BarcodeDetectorDouble {
    static async getSupportedFormats() {
      return ["ean_8", "ean_13", "itf", "upc_a", "upc_e"];
    }

    constructor(options: { formats: readonly string[] }) {
      requestedFormats = options.formats;
    }

    detect = detect;
  }
  Object.defineProperty(globalThis, "BarcodeDetector", {
    configurable: true,
    value: BarcodeDetectorDouble,
  });
  const frames: FrameRequestCallback[] = [];
  globalThis.requestAnimationFrame = vi.fn((callback: FrameRequestCallback) => {
    frames.push(callback);
    return frames.length;
  });
  globalThis.cancelAnimationFrame = vi.fn();
  const candidates: string[] = [];
  const terminalErrors: unknown[] = [];

  const session = await localBarcodeDecoder.start(
    {} as HTMLVideoElement,
    (barcode) => candidates.push(barcode),
    (error) => terminalErrors.push(error),
  );
  expect(requestedFormats).toEqual([
    "ean_8",
    "ean_13",
    "itf",
    "upc_a",
    "upc_e",
  ]);
  expect(candidates).toEqual([]);

  frames.shift()!(0);
  await vi.waitFor(() => expect(candidates).toEqual(["034000470693"]));
  expect(terminalErrors).toEqual([]);

  frames.shift()!(1);
  await vi.waitFor(() => expect(candidates).toEqual([
    "034000470693",
    "034000470693",
  ]));

  session.stop();
  expect(globalThis.cancelAnimationFrame).toHaveBeenCalledOnce();
  const detectCalls = detect.mock.calls.length;
  frames.shift()?.(1);
  expect(detect).toHaveBeenCalledTimes(detectCalls);
});

test("the bundled decoder receives every format and ignores ordinary misses", async () => {
  Reflect.deleteProperty(globalThis, "BarcodeDetector");
  const candidates: string[] = [];
  const terminalErrors: unknown[] = [];

  const session = await localBarcodeDecoder.start(
    {} as HTMLVideoElement,
    (barcode) => candidates.push(barcode),
    (error) => terminalErrors.push(error),
  );

  expect(zxingHarness.hints?.get(DecodeHintType.POSSIBLE_FORMATS)).toEqual([
    BarcodeFormat.EAN_8,
    BarcodeFormat.EAN_13,
    BarcodeFormat.ITF,
    BarcodeFormat.UPC_A,
    BarcodeFormat.UPC_E,
  ]);
  expect(zxingHarness.options).toEqual({
    delayBetweenScanAttempts: 100,
    delayBetweenScanSuccess: 100,
  });
  const controls = {} as never;
  zxingHarness.callback?.(undefined, new NotFoundException(), controls);
  zxingHarness.callback?.(undefined, new ChecksumException(), controls);
  zxingHarness.callback?.(undefined, new FormatException(), controls);
  expect(candidates).toEqual([]);
  expect(terminalErrors).toEqual([]);
  session.stop();
  expect(zxingHarness.sessionStop).toHaveBeenCalledOnce();
});

test("the bundled decoder emits valid results and reports unexpected failures", async () => {
  Reflect.deleteProperty(globalThis, "BarcodeDetector");
  const candidates: string[] = [];
  const terminalErrors: unknown[] = [];

  await localBarcodeDecoder.start(
    {} as HTMLVideoElement,
    (barcode) => candidates.push(barcode),
    (error) => terminalErrors.push(error),
  );

  const controls = {} as never;
  zxingHarness.callback?.({
    getText: () => "not-a-barcode",
  } as never, undefined, controls);
  zxingHarness.callback?.({
    getText: () => " 034000470693 ",
  } as never, undefined, controls);
  const frameFailure = new Error("canvas failed");
  zxingHarness.callback?.(undefined, frameFailure as never, controls);

  expect(candidates).toEqual(["034000470693"]);
  expect(terminalErrors).toEqual([frameFailure]);
});

test("an incomplete native detector falls back without constructing it", async () => {
  const constructed = vi.fn();
  class PartialBarcodeDetectorDouble {
    static async getSupportedFormats() {
      return ["ean_13"];
    }

    constructor() {
      constructed();
    }
  }
  Object.defineProperty(globalThis, "BarcodeDetector", {
    configurable: true,
    value: PartialBarcodeDetectorDouble,
  });

  await localBarcodeDecoder.start(
    {} as HTMLVideoElement,
    () => undefined,
    () => undefined,
  );

  expect(constructed).not.toHaveBeenCalled();
  expect(zxingHarness.callback).toBeTypeOf("function");
});

test("native transient and terminal errors have distinct frame behavior", async () => {
  const transient = new Error("not ready");
  transient.name = "InvalidStateError";
  const terminal = new Error("detector failed");
  const detect = vi.fn()
    .mockRejectedValueOnce(transient)
    .mockRejectedValueOnce(terminal);
  class BarcodeDetectorDouble {
    static async getSupportedFormats() {
      return ["ean_8", "ean_13", "itf", "upc_a", "upc_e"];
    }

    detect = detect;
  }
  Object.defineProperty(globalThis, "BarcodeDetector", {
    configurable: true,
    value: BarcodeDetectorDouble,
  });
  const frames: FrameRequestCallback[] = [];
  globalThis.requestAnimationFrame = vi.fn((callback: FrameRequestCallback) => {
    frames.push(callback);
    return frames.length;
  });
  const terminalErrors: unknown[] = [];

  await localBarcodeDecoder.start(
    {} as HTMLVideoElement,
    () => undefined,
    (error) => terminalErrors.push(error),
  );
  frames.shift()!(0);
  await vi.waitFor(() => expect(frames).toHaveLength(1));
  expect(terminalErrors).toEqual([]);
  frames.shift()!(1);
  await vi.waitFor(() => expect(terminalErrors).toEqual([terminal]));
  expect(frames).toHaveLength(0);
});

