    () => new Date("2026-08-29T18:00:00.000Z"),
  ).log(userId, {
    foodLogDate: "2026-08-29",
    idempotencyKey: "0198f7e2-5aab-7000-8000-000000000002",
    provider: "usda-fdc",
    providerFoodId: "200",
    quantity: "1",
