  });
  expect(input(renderer, "sodium").props).toMatchObject({
    max: "100000",
    min: "1",
    step: "1",
    value: "2300",
  });
  expect(input(renderer, "protein").props).toMatchObject({
    max: "2000",
    min: "0.001",
    step: "0.001",
    value: "120",
  });
  expect(renderer.root.findAllByType("em").map((node) => nodeText(node)))
    .toEqual(["kcal", "fl oz", "g", "g", "g", "g", "g", "mg"]);
