      async getFood() {
        throw new Error("unused");
      },
      async search() {
        return [];
      },
    };
    setFoodCatalogProviderForTests(replacement);
    expect(getFoodCatalogProvider()).toBe(replacement);
    expect(getFoodCatalogProvider()).toBe(replacement);
